from rules import dependency, in_range


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', []) or []
    names = sorted(packages)
    best = None
    best_vector = None

    def is_acyclic(graph, vertices):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for target in graph.get(name, ()):
                if target in vertices and not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in vertices)

    def search(selected, constraints, graph):
        nonlocal best, best_vector

        for name, row in selected.items():
            if name not in constraints or not in_range(row['version'], constraints[name]):
                return

        unresolved = [name for name in constraints if name not in selected]
        if not unresolved:
            if not is_acyclic(graph, set(selected)):
                return
            vector = tuple(selected[name]['version'] if name in selected else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: row['version'] for name, row in selected.items()}
            return

        name = min(unresolved)
        forbidden = blocked.get(name, [])
        candidates = [row for row in packages.get(name, [])
                      if row['version'] not in forbidden
                      and (name not in pins or row['version'] == pins[name])
                      and in_range(row['version'], constraints[name])]
        candidates.sort(key=lambda row: row['version'], reverse=True)

        for row in candidates:
            next_selected = dict(selected)
            next_selected[name] = row
            next_constraints = dict(constraints)
            next_graph = dict(graph)
            valid = True

            for dep in row.get('deps', []):
                if isinstance(dep, dict):
                    feature = dep.get('feature')
                    if feature and feature not in features:
                        continue

                target, bounds = dependency(dep)
                if not target or target not in packages:
                    valid = False
                    break

                if target in next_constraints:
                    old = next_constraints[target]
                    lo = max(old[0], bounds[0])
                    hi = min(old[1], bounds[1])
                    if lo > hi:
                        valid = False
                        break
                    next_constraints[target] = (lo, hi)
                else:
                    next_constraints[target] = bounds

                if target in next_selected and not in_range(
                        next_selected[target]['version'], next_constraints[target]):
                    valid = False
                    break

                next_graph[name] = next_graph.get(name, ()) + (target,)

            if valid:
                search(next_selected, next_constraints, next_graph)

    initial = {}
    valid_roots = True
    for name, bounds in roots.items():
        if name not in packages:
            valid_roots = False
            break
        initial[name] = tuple(bounds)

    if valid_roots:
        search({}, initial, {})

    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

import re

_INF = float('inf')
_NINF = float('-inf')


def in_range(version, bounds):
    return bounds[0] <= version <= bounds[1]


def _bounds(value):
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        return value[0], value[1]
    if isinstance(value, dict):
        lo = value.get('min', value.get('minimum', value.get('min_version', _NINF)))
        hi = value.get('max', value.get('maximum', value.get('max_version', _INF)))
        return lo, hi
    return _NINF, _INF


def dependency(dep):
    if isinstance(dep, str):
        match = re.fullmatch(r'\s*([A-Za-z0-9_.-]+)\s*(?:(>=|<=|==|>|<)\s*(-?\d+))?\s*', dep)
        if not match:
            return None, (_NINF, _INF)
        name, op, value = match.groups()
        if op is None:
            bounds = (_NINF, _INF)
        else:
            number = int(value)
            bounds = {
                '>=': (number, _INF), '<=': (_NINF, number),
                '==': (number, number), '>': (number + 1, _INF),
                '<': (_NINF, number - 1),
            }[op]
        return name, bounds

    if isinstance(dep, (list, tuple)) and dep:
        name = str(dep[0])
        if len(dep) == 2:
            return name, _bounds(dep[1])
        if len(dep) >= 3:
            return name, (dep[1], dep[2])
        return name, (_NINF, _INF)

    if isinstance(dep, dict):
        name = next((dep[key] for key in ('name', 'package', 'target', 'dependency')
                     if key in dep), None)
        if name is None and len(dep) == 1:
            name, value = next(iter(dep.items()))
            return str(name), _bounds(value)
        if name is None:
            return None, (_NINF, _INF)
        bounds = _bounds(dep.get('range', dep.get('versions', dep.get('version'))))
        lo = dep.get('min', dep.get('minimum', dep.get('min_version', bounds[0])))
        hi = dep.get('max', dep.get('maximum', dep.get('max_version', bounds[1])))
        return str(name), (lo, hi)

    return None, (_NINF, _INF)


def choose(rows):
    return max(rows, key=lambda row: row['version'])
